/**
 * D99: hunting spots (TibiaWiki hunting places) with their creatures, generated by `npm run import:spots`.
 * Weights are shares of weekly kills (%) where they are reliable, otherwise 1.
 */
import spotsJson from './spots.json';

export interface HuntingSpot {
  name: string;
  /** Other common names (the wiki title when the spot is shown under a common name). */
  aliases?: string[];
  monsters: { id: string; weight: number }[];
}

export const SPOTS: readonly HuntingSpot[] = (spotsJson as { spots: HuntingSpot[] }).spots;

const share = (s: HuntingSpot, id: string) => {
  const sum = s.monsters.reduce((a, m) => a + m.weight, 0);
  return (s.monsters.find((m) => m.id === id)?.weight ?? 0) / sum;
};

const BY_MONSTER = new Map<string, HuntingSpot[]>();
for (const s of SPOTS) for (const m of s.monsters) BY_MONSTER.set(m.id, [...(BY_MONSTER.get(m.id) ?? []), s]);
for (const [id, list] of BY_MONSTER) list.sort((a, b) => share(b, id) - share(a, id) || a.name.localeCompare(b.name, 'en'));

/** Spots with the monster, the ones where it is the largest share first. */
export function spotsWithMonster(id: string): readonly HuntingSpot[] {
  return BY_MONSTER.get(id) ?? [];
}
